WITH filtered_subscriptions AS (SELECT *, LENGTH(status) AS status_length FROM subscriptions WHERE end_date > '2023-09-01' AND MONTH(end_date) IN (5, 8, 12)), summary AS (SELECT plan, COUNT(DISTINCT monthly_fee) AS unique_statuss, ROUND(AVG(status_length), 2) AS avg_status_length FROM filtered_subscriptions GROUP BY plan) SELECT * FROM summary WHERE unique_statuss >= 5 ORDER BY avg_status_length DESC, plan LIMIT 20;
